"""Shannon entropy and linguistic analysis Domain Generation Algorithm (DGA) detector."""

import math
from collections import Counter
from typing import Tuple


class DGADetector:
    """Detects algorithmic C2 domains generated by malware families via entropy and consonant clustering."""

    VOWELS = set("aeiou")

    @classmethod
    def calculate_entropy(cls, text: str) -> float:
        """Calculate Shannon entropy for character distribution."""
        if not text:
            return 0.0
        counts = Counter(text.lower())
        total = len(text)
        entropy = 0.0
        for count in counts.values():
            p = count / total
            entropy -= p * math.log2(p)
        return round(entropy, 3)

    @classmethod
    def get_vowel_ratio(cls, text: str) -> float:
        """Calculate vowel to total alphabet character ratio."""
        alphas = [c for c in text.lower() if c.isalpha()]
        if not alphas:
            return 0.0
        vowel_count = sum(1 for c in alphas if c in cls.VOWELS)
        return round(vowel_count / len(alphas), 3)

    @classmethod
    def evaluate(
        cls,
        domain: str,
        entropy_threshold: float = 3.5,
        min_label_length: int = 10,
    ) -> Tuple[bool, float, str]:
        """Evaluate if domain is likely generated by a DGA algorithm.

        Returns:
            Tuple[bool, float, str]: (is_dga, entropy_score, reason)
        """
        clean = domain.strip().lower().rstrip(".")
        labels = clean.split(".")
        main_label = labels[0] if labels else ""

        if len(main_label) < min_label_length:
            return False, cls.calculate_entropy(main_label), "label_too_short"

        entropy = cls.calculate_entropy(main_label)
        vowel_ratio = cls.get_vowel_ratio(main_label)

        # High entropy + abnormal vowel ratio indicates DGA
        is_suspicious_entropy = entropy >= entropy_threshold
        is_unnatural_consonants = (vowel_ratio < 0.18 or vowel_ratio > 0.75) and len(main_label) >= 12

        if is_suspicious_entropy and is_unnatural_consonants:
            return True, entropy, f"DGA High Entropy ({entropy}) & Unnatural Vowel Ratio ({vowel_ratio})"
        elif is_suspicious_entropy:
            return True, entropy, f"DGA High Entropy ({entropy})"
        return False, entropy, "benign_lexical_characteristics"
